T cut_pos[3];
int minCostAxis = -1;
int numBins = bins->num_bins;
T bin_width[3];
T inv_bin_width[3];
for (int i = 0; i < 3; i++) {
    bin_width[i] = (bmax[i] - bmin[i]) / numBins;
    inv_bin_width[i] = 1.0 / bin_width[i];
}

T minCost = std::numeric_limits<T>::max();
for (int axis = 0; axis < 3; axis++) {
    T cost = 0.0;
    for (int i = 0; i < numBins; i++) {
        T left = 0.0;
        T right = 0.0;
        for (int j = 0; j < numBins; j++) {
            if (j < i) {
                left += bins->bin_count[axis * numBins + j];
            } else {
                right += bins->bin_count[axis * numBins + j];
            }
        }
        cost += (left * right) * bin_width[axis];
    }
    if (cost < minCost) {
        minCost = cost;
        minCostAxis = axis;
    }
}

if (minCostAxis != -1) {
    T total = 0.0;
    for (int i = 0; i < numBins; i++) {
        total += bins->bin_count[minCostAxis * numBins + i];
    }
    T threshold = total / 2.0;
    T sum = 0.0;
    for (int i = 0; i < numBins; i++) {
        sum += bins->bin_count[minCostAxis * numBins + i];
        if (sum >= threshold) {
            cut_pos[minCostAxis] = bmin[minCostAxis] + (i + 0.5) * bin_width[minCostAxis];
            break;
        }
    }
    cut_pos[(minCostAxis + 1) % 3] = 0.0;
    cut_pos[(minCostAxis + 2) % 3] = 0.0;
    *minCostAxis = minCostAxis;
    return true;
} else {
    return false;
}

